lxi('ask_how', 'How are you? I mean really, not the answer you give the baker.', { rel: 'spouse' }); lxi('ask_how', 'Are you well? You look tired. You always look tired. It is part of the family.', { rel: 'parent' }); lxi('ask_how', 'Are you behaving? Do not answer.', { rel: 'child', kid: 'yes' }); lxi('ask_how', 'How is life, then? Tell me before everyone else does.', { rel: 'sibling' });

/* ---- backchannel: a nod to what was said ---- */
ACTS.backchannel = { kind: 'small', stage: 'topic', reply: true, when: () => true, w: () => 1, apply: () => {}, replies: [] };
lx('backchannel', 'plain', 'Mm.'); lx('backchannel', 'plain', 'I see.'); lx('backchannel', 'plain', 'Right.'); lx('backchannel', 'plain', 'Is that so.'); lx('backchannel', 'plain', 'Ah.');
lxi('backchannel', 'Mm.'); lxi('backchannel', 'I see.'); lxi('backchannel', 'Yes. Well.'); lxi('backchannel', 'That is something.'); lxi('backchannel', 'Ah. Yes.');

/* ---- how children talk (under twelve): short, direct, and about what a child is busy with ---- */
const kidl = (act: string, text: string, tags: any = {}) => { lx(act, 'plain', text, Object.assign({ age: 'child' }, tags)); };
const kidi = (act: string, text: string, tags: any = {}) => { lxi(act, text, Object.assign({ age: 'child' }, tags)); };
kidl('greet', 'Hi!'); kidl('greet', 'Hello, {li}! Look what I found.'); kidl('greet', 'Are you going anywhere? Can I come?'); kidl('greet_back', 'Hi!'); kidl('greet_back', 'Hello! I was playing.'); kidl('greet_back', 'Oh, hello. I\'m busy.');
kidl('farewell', 'Bye! I\'m going to play.'); kidl('farewell', 'See you! Don\'t tell anyone.'); kidl('farewell_back', 'Bye!'); kidl('pre_close', 'I have to go. I\'m in the middle of something.'); kidl('pre_close', 'Can I go now?');
kidl('answer_how', 'Fine! I found a good stick.', { state: 'fine' }); kidl('answer_how', 'I\'m hungry. Is it supper yet?', { state: 'hungry' }); kidl('answer_how', 'I\'m tired. I\'m not tired. I\'m tired.', { state: 'tired' }); kidl('answer_how', 'Great! I\'m having a good day!', { state: 'glad' });
kidl('agree', 'Yes!'); kidl('agree', 'I know!'); kidl('remark_time', 'Is it time for lunch yet?'); kidl('remark_time', 'It\'s a long day when you\'re small.'); kidl('remark_place', 'I like it here. There\'s room to run.'); kidl('remark_work', 'I\'m helping. Mostly I\'m watching.');
kidi('greet', 'Hello. I am small, but I noticed you.'); kidi('greet', 'Hello, {li}. I found something. I will not say what.'); kidi('greet', 'Are you going somewhere? I could come. I would be quiet. Mostly.'); kidi('greet_back', 'Hello. I was doing something important.'); kidi('greet_back', 'Hello. I am small, but I am here.');
kidi('farewell', 'Bye. I am going to go and do something. I will not say what.'); kidi('farewell', 'Bye. Do not tell them where I went.'); kidi('farewell_back', 'Bye.'); kidi('pre_close', 'I have to go. There is a thing I am in the middle of.'); kidi('pre_close', 'Can I go now? I am asking nicely.');
kidi('answer_how', 'Fine. I found a very good stick.', { state: 'fine' }); kidi('answer_how', 'I am hungry. Is it nearly supper? It feels nearly.', { state: 'hungry' }); kidi('answer_how', 'I am tired. I am not tired. I am a bit tired.', { state: 'tired' }); kidi('answer_how', 'Good. It has been a good day. I did not expect that of it.', { state: 'glad' });
kidi('agree', 'Yes.'); kidi('agree', 'I know. I was going to say that.'); kidi('remark_time', 'Is it lunch yet? It feels like lunch.'); kidi('remark_time', 'It is a long day when you are small.'); kidi('remark_place', 'I like it here. There is room to run, and nobody has said not to.'); kidi('remark_work', 'I am helping. Mostly I am watching. It is also work.');

/* ---- more ways to say the little things (the same hello twenty times a day is what makes a village sound like a script) ---- */
for (const t of ['Good to see you, {li}.', 'Oh, {li}. How are things?', 'Hey, {li}.', 'Well met, {li}.', '{li}! Just the person.', 'Ah, {li}.', 'Busy day, {li}?', 'Hello there, {li}.', 'Is that you, {li}? It is.']) lx('greet', 'plain', t);
for (const t of ['Hello to you.', 'Ah, hello.', 'Oh! Hello, {li}.', 'Good to see you too.', 'Hello, hello.', 'There you are.', 'Hello. How are you?', 'Hey.', 'Well. Hello.']) lx('greet_back', 'plain', t);
for (const t of ['I\'d better get on.', 'Well. Work waits.', 'Must dash.', 'I won\'t keep you.', 'That\'s me, then.', 'Right. Off I go.', 'Mustn\'t stand about.', 'Time I wasn\'t here.', 'I should leave you to it.']) lx('pre_close', 'plain', t);
for (const t of ['Take care, {li}.', 'Until next time.', 'Safe on your way.', 'Good day to you.', 'Be well.', 'Mind how you go.', 'Cheerio.', 'Look after yourself.', 'All the best.']) lx('farewell', 'plain', t);
for (const t of ['And you.', 'Take care.', 'Be well.', 'Right you are.', 'Goodbye, then.', 'Off you go.', 'See you around.', 'Cheers.', 'Until then.']) lx('farewell_back', 'plain', t);
for (const t of ['I know.', 'Quite.', 'True enough.', 'That\'s right.', 'Exactly so.', 'I\'d say so.', 'Yes. Quite.', 'Without a doubt.', 'You\'re not wrong.']) lx('agree', 'plain', t);
for (const t of ['Hello. I did not expect to see you, and yet.', 'Ah, {li}. I was just thinking of something else.', 'Good. You are here. I was about to start talking to myself.', 'Hello. It is a day of some kind.', '{li}. Yes. There you are.', 'Ah. Company. I had been preparing for none.', 'Hello, {li}. I will say it first this time.', 'Hello. I see you have arrived, as one does.', '{li}. Good. I had a thought and nobody to give it to.']) lxi('greet', t);
for (const t of ['Hello. I was about to say that.', 'Ah. Hello. I had a feeling.', 'Hello. I am pleased and slightly startled.', 'Yes. Hello. It is that time.', 'Hello. Come to think of it, I was hoping.', 'Hello to you, in return.', 'Good. Hello. That is out of the way.', 'Hello. I have been standing here on purpose.', 'Ah, {li}. The island does arrange things.']) lxi('greet_back', t);
for (const t of ['I should get on. The day has noticed me.', 'Well. That is that, for now.', 'I will leave you to it. You were doing something.', 'That is the end of what I had.', 'I should go. I will pretend I have a reason.', 'I have a few things to be near. I will go and be near them.', 'Right. The afternoon will want me soon.', 'I will let the conversation end here. It has had a good run.', 'Off I go. I will not look back, which is a lie.']) lxi('pre_close', t);
for (const t of ['Take care, {li}. The island is small but it has edges.', 'Until next time. I will be somewhere.', 'Be well. I mean it in the ordinary way.', 'Goodbye, {li}. It was a good length.', 'Mind how you go. There is a lot of ground.', 'Look after yourself. Somebody has to, and I am here.', 'All the best. I have no better phrase.', 'Good day to you. It is, so far.', 'See you. I say it as a matter of course.']) lxi('farewell', t);
for (const t of ['And you.', 'Yes. Goodbye.', 'Be well, then.', 'Off you go. I will watch for a moment.', 'See you. I will be here, or near.', 'Goodbye. It was good.', 'Quite. Goodbye.', 'Right. Until then.', 'And the same to you, exactly.']) lxi('farewell_back', t);
for (const t of ['Yes. I was going to say that.', 'Quite. It is what I think too.', 'That is right. I am glad somebody said it.', 'True. It does not make it simpler.', 'I agree. I wish I did not.', 'Yes. That is it exactly.', 'Mm. Yes. I would put it that way.', 'You are right. I have been thinking so since Tuesday.', 'Agreed. That is a rare thing.']) lxi('agree', t);
for (const t of ['Fine, thanks. You?', 'Can\'t grumble.', 'Getting by.', 'Not bad. Not bad at all.', 'Same as ever.', 'Well enough.', 'Mustn\'t complain.', 'Fair to middling.']) lx('answer_how', 'plain', t, { state: 'fine' });
for (const t of ['Fine. I looked into it and there is nothing to report.', 'Fine. The day has not asked much of me.', 'Well enough. I have checked.', 'About a five. A good, honest five.', 'Fine. There is a small noise in my left knee, which is the news.', 'Fine. I was going to say I was well and it is true, which surprised me.', 'Steady. That is the word I have settled on.', 'Not bad. I say that and wait for the day to hear me.']) lxi('answer_how', t, { state: 'fine' });
for (const t of ['Better than I deserve.', 'Grand, really.', 'On top of the world, nearly.', 'Very well, as it happens.']) lx('answer_how', 'plain', t, { state: 'glad' });
for (const t of ['Good. I would like to say why. I cannot.', 'Very well. I have decided to enjoy it before it is noticed.', 'Better than I expected. I recalibrated my expectations on the way here.', 'Well. In a way that does not need explaining.']) lxi('answer_how', t, { state: 'glad' });
for (const t of ['Not great, to be honest.', 'Low. It\'ll pass.', 'I\'ve had better days.', 'Could be better.']) lx('answer_how', 'plain', t, { state: 'low' });
for (const t of ['Low. It has no address, so I cannot send it back.', 'Not well. It is a grey kind of not well, not an interesting one.', 'I have had better days. I could name three.', 'Flat. Like a field after rain, if the field had opinions.']) lxi('answer_how', t, { state: 'low' });
for (const t of ['Hungry! Starving, nearly.', 'Hungry, to be honest. My stomach\'s been talking.', 'Starving. Is there bread?']) lx('answer_how', 'plain', t, { state: 'hungry' });
for (const t of ['Hungry. It is a precise feeling and I recognise it.', 'Hungry. My stomach has started to make announcements.', 'Hungry. I have thought about bread more than is dignified.']) lxi('answer_how', t, { state: 'hungry' });
for (const t of ['Tired. Could sleep standing.', 'Worn out, honestly.', 'Weary to the bone.']) lx('answer_how', 'plain', t, { state: 'tired' });
for (const t of ['Tired. I could sleep standing. I may be.', 'Worn out. The kind that sits behind the eyes.', 'Tired in a way that sleep might help.']) lxi('answer_how', t, { state: 'tired' });
for (const t of ['How are things?', 'How\'s the day treating you?', 'Keeping well?', 'And how are you?', 'How\'ve you been keeping?']) lx('ask_how', 'plain', t);
for (const t of ['How are you holding up?', 'How is the day treating you? I mean honestly.', 'Are you keeping well? I ask in case.', 'How have you been, since last time? Give me the short version.', 'And you? How are things on your side of the island?']) lxi('ask_how', t);

lx('thanks_where', 'plain', 'Thanks. I\'ll go and find {them}.'); lx('thanks_where', 'plain', 'Right. That\'s where I\'ll look.'); lxi('thanks_where', 'Thank you. I will go and look there. I may not find {them}, but I will have gone.'); lxi('thanks_where', 'Good. That is somewhere to start.');
/* ---- responsive talk: a bad answer gets a reaction ---- */
ACTS.answer_how.replies = ['sympathise_how', 'share_gladness'];
ACTS.sympathise_how = { kind: 'feeling', stage: 'topic', reply: true, when: (c: any) => ['low', 'tired', 'hungry'].includes(c.state), w: () => 3, apply: (c: any, sp: any, li: any) => { li.mood = Math.min(100, (li.mood == null ? 50 : li.mood) + 2); lfAff(li, sp, 1, 'asked after me'); }, replies: [] };
ACTS.share_gladness = { kind: 'feeling', stage: 'topic', reply: true, when: (c: any) => c.state === 'glad', w: () => 2, apply: () => {}, replies: [] };
lx('sympathise_how', 'plain', 'Oh. I\'m sorry to hear that.', { state: 'low' }); lx('sympathise_how', 'plain', 'Do you want to talk about it? I\'ve time.', { state: 'low' }); lx('sympathise_how', 'plain', 'You should eat something. Have you tried the baker?', { state: 'hungry' }); lx('sympathise_how', 'plain', 'Get some bread in you. It\'ll help.', { state: 'hungry' }); lx('sympathise_how', 'plain', 'Get some rest if you can. The day will keep.', { state: 'tired' }); lx('sympathise_how', 'plain', 'You look it. Sit down for a minute.', { state: 'tired' });
lxi('sympathise_how', 'I am sorry. I would offer something, but I have only the sentence.', { state: 'low' }); lxi('sympathise_how', 'Do you want to talk about it? I have time. I have, in fact, nothing but time.', { state: 'low' }); lxi('sympathise_how', 'You should eat. I say it as a person who has also been hungry on this island.', { state: 'hungry' }); lxi('sympathise_how', 'Bread. Find bread. That is the whole of my advice and I stand by it.', { state: 'hungry' }); lxi('sympathise_how', 'Rest if you can. The day will wait. It is good at that.', { state: 'tired' }); lxi('sympathise_how', 'You look it. Sit down. The ground is free.', { state: 'tired' });
lx('share_gladness', 'plain', 'Good. I\'m glad to hear it.'); lx('share_gladness', 'plain', 'That\'s good to hear.'); lxi('share_gladness', 'Good. I am glad. I will try not to be suspicious of it.'); lxi('share_gladness', 'Good. Hold on to it. It does not come in great quantity.');

for (const t of ['Nothing new. I\'d tell you.', 'Not since, no.', 'A little. Not much to tell.', 'Same as before, really.', 'Oh, don\'t ask. Well. Do ask. Later.', 'Better, I think. Thanks for remembering.']) lx('callback_answer', 'plain', t);
for (const t of ['No change. I will tell you if there is.', 'A little. It is too early to say what kind.', 'It has gone quiet, which I am choosing to see as progress.', 'I thought about it again after you left. That was the only development.', 'Better, I think. I have stopped checking.', 'Worse, in a small way. I am keeping an eye on it.']) lxi('callback_answer', t);
for (const t of ['Good going.', 'That\'s a fair day.', 'Well done.', 'Not bad at all.', 'Sounds like it went well.', 'That\'s something to be glad of.']) lx('acknowledge', 'plain', t);
for (const t of ['That is a respectable day.', 'Good. I would call that a day.', 'That sounds like it went well. I will take your word for it.', 'Well done. I mean that in a measured way.', 'That is more than I managed, so well done.', 'Good. Somebody should have a good day. It might as well be you.']) lxi('acknowledge', t);

for (const t of ['Is that so. I had not noticed.', 'Hm. I will have a look.', 'Odd. But there we are.', 'Well. If you say so.', 'Is it. Well.']) lx('acknowledge', 'plain', t, { how: 'neutral' });
for (const t of ['I see. I will keep an eye on it, from a distance.', 'Is that so. I had not noticed, which says something about me.', 'Hm. That is something to know.', 'Well. If you say so. I am inclined to.', 'Odd. And yet it is the sort of thing that happens here.']) lxi('acknowledge', t, { how: 'neutral' });
for (const t of ['Good going.', 'That is a fair day.', 'Well done.', 'Sounds like it went well.']) lx('acknowledge', 'plain', t, { how: 'good' });
for (const t of ['That is a respectable day.', 'Well done. I mean it in a measured way.', 'That sounds like it went well. I will take your word for it.', 'Good. Somebody should have a good day.']) lxi('acknowledge', t, { how: 'good' });

for (const t of ['{about} was {reason}, the last I saw.', 'Try {reason}. That is where {about} was.', 'I passed {about} {reason} not long ago.', '{about}? {reason}, I believe.']) lx('tell_where', 'plain', t);
for (const t of ['{about} is {reason}. I looked, on the way past. I do not know why.', '{about} was {reason} a short while ago. People stay where they are, mostly.', 'Try {reason}. I would not swear to it. I would swear to most of it.', '{about} is {reason}. I saw them from a distance, which is how I see most people.', 'I think {about} is {reason}. I have a good feeling about that, in a general way.']) lxi('tell_where', t);
for (const t of ['Thanks. I\'ll try there.', 'Right. Good to know.', 'Ah. Thanks, I\'ll go and see.']) lx('thanks_where', 'plain', t);
for (const t of ['Thank you. That narrows it down.', 'Good. That is somewhere to start. Thank you.', 'Right. I will walk that way and see what the island says.']) lxi('thanks_where', t);

/* ---- more to say: the acts people use most needed the most lines ---- */
const LXP = (act: string, lines: string[], tags: any = {}) => { for (const t of lines) lx(act, 'plain', t, tags); };
const LXI = (act: string, lines: string[], tags: any = {}) => { for (const t of lines) lxi(act, t, tags); };
LXP('ask_opinion', ["What do you think of {about}?", "Be honest. How do you find {about}?", "How do you get on with {about}?", "{about}. What\'s your view?", "Tell me about {about}. Properly."]);
LXI('ask_opinion', ["How do you find {about}? I am asking out of something between curiosity and need.", "What is your view of {about}? I would like one, and I am short.", "Tell me about {about}. Leave out the weather.", "{about}. What do you make of them? Take your time. I have mine.", "How are you with {about}? I never know how people are with people."]);
LXP('ask_family', ["How\'s {about} keeping?", "And how is {about}? Still the same?", "Is {about} all right? I haven\'t seen them.", "How\'s {about} been lately?", "Tell {about} I was asking after them."]);
LXI('ask_family', ["How is {about} getting on? I mean in the exact sense.", "And {about}? I have not seen {about} in a while, which is how I know I should ask.", "How has {about} been, since the last time we spoke of {about}?", "Is {about} all right? Say yes if you can and the truth if you cannot.", "Give me the short version of {about}."]);
LXP('agree_opinion', ["That\'s how I see it too.", "Exactly my feeling.", "I\'ve always thought so.", "Well said. I couldn\'t put it better.", "Mm. Same here."]);
LXI('agree_opinion', ["That is how I see it as well. It is a relief to find out.", "Exactly. I have had that opinion for some time and nowhere to put it.", "Yes. I had begun to think I imagined it.", "I agree. I did not want to be the first to say.", "Same. It is nice to be wrong in company, if we are."]);
LXP('remark_place', ["Pleasant enough {place}.", "I like it {place} at this hour.", "{place} is a good spot for a think.", "Never changes, {place}. I like that.", "Always something going on {place}."]);
LXI('remark_place', ["I come {place} more than I mean to. I think the ground is fond of me.", "{place}. It looks the same as it did, which I am treating as good news.", "Something is slightly different {place}. I cannot find what. I will keep looking.", "I like it {place} when nobody is. I like it with you here too. That is a small lie.", "It is quieter {place} than it used to be. Or I am louder."]);
LXP('ask_news', ["Anything new?", "What\'s the talk?", "Heard anything worth hearing?", "Any word from anywhere?", "Anything I\'ve missed?"]);
LXI('ask_news', ["Is there news? I would settle for a small rumour.", "What is being said? I mean by people, not the wind.", "Have you heard anything I have not? That is a low bar and I would be pleased.", "Anything new? I have been staring at the same thing for hours.", "What is the island saying today? I am prepared to be unsurprised."]);
LXP('no_news', ["Nothing I\'d repeat.", "Quiet as anything.", "Not a word. Not a whisper.", "Nothing at all. I\'d tell you.", "Not that I\'ve heard."]);
LXI('no_news', ["Nothing. I checked the usual places. They were the usual.", "Nothing. A cloud went over. That was about all of it.", "Nothing I would call news. A man looked at a wall for some time. That was it.", "Nothing. I will tell you the moment there is something, which will be after you have already heard.", "No. The island is keeping its counsel today. It does that.", "Nothing. Somebody sneezed near the well. People talked of nothing else for a minute."]);
LXP('ask_price', ["What would {item} cost me now?", "Do you know the going rate for {item}?", "What are you seeing for {item}?", "Is {item} dear at the moment?", "Heard what {item} fetch?"]);
LXI('ask_price', ["What does {item} cost these days? I will need a number, not a mood.", "Do you know the price of {item}? I do not, and I dislike not.", "What are {item} fetching? I have a figure in mind and no faith in it.", "Is {item} dear just now? Give me a figure and I will give you my opinion of it.", "How much for {item}, lately? I am collecting numbers."]);
LXP('tell_price', ["{money}, last I looked.", "About {money} each, I think.", "It was {money} the other day.", "{money}. It\'s fair.", "{money} and not a coin less."]);
LXI('tell_price', ["{money}. I counted it twice, then a third time, for company.", "About {money}. It was that when I stopped looking.", "{money} each. I am reporting, not recommending.", "{money}. I did not argue. I do not know how.", "{money}. The number has been the same for a while, which is a comfort."]);
LXP('answer_family', ["{about} is fine. Same as ever.", "{about}\'s doing well, thanks for asking.", "{about} is keeping busy."], { state: 'fine' });
LXI('answer_family', ["{about} is fine. I have looked, and they appear to be.", "{about} is well. I am as surprised as you.", "{about} is busy. I say it with pride and mild alarm."], { state: 'fine' });
LXP('answer_family', ["{about} is on top of the world, for once.", "{about}\'s in a grand mood."], { state: 'glad' });
LXI('answer_family', ["{about} is cheerful. I do not know why and I am being careful with it.", "{about} is in a good mood. It has the feel of weather."], { state: 'glad' });
LXP('answer_family', ["{about}\'s not been right lately.", "{about} is low. Worries me a bit."], { state: 'low' });
LXI('answer_family', ["{about} is low. I do not have the cure. I have a blanket, which I have offered.", "{about} has been quiet in a way I do not like."], { state: 'low' });
LXP('answer_family', ["{about} is worn out. Needs a good rest.", "{about} is tired through. Can\'t blame them."], { state: 'tired' });
LXI('answer_family', ["{about} is tired. The kind that is also a mood.", "{about} is worn out. I have suggested sleep. It was received with suspicion."], { state: 'tired' });
LXP('praise', ["You\'ve a way of making a day better. Just so you know.", "I don\'t say it enough: I\'m glad of you.", "You\'re one of the good ones, you are."]);
LXI('praise', ["You make the island more bearable. I did not plan to say it, and now it is said.", "I wanted to say that you are easy to be around. I have checked, and it is true.", "You are good at being here. That is rarer than it sounds."]);
LXP('thank_praise', ["Well. Thanks. That\'s made my day.", "You\'ll make me blush. Thank you.", "That\'s kind. I\'ll keep it."]);
LXI('thank_praise', ["Thank you. I am going to be careful with that. It is a delicate thing to be handed.", "That is kind. I will think about it at a quiet moment.", "Thank you. I do not know what to do with my face."]);
LXP('react_price', ["That\'s about what I expected.", "Dearer than last time.", "Cheaper than I feared.", "Fair enough. I\'ll think on it."]);
LXI('react_price', ["That is about what I expected. I am disappointed to be right.", "Dearer. I will complain to the air and then pay it.", "Cheaper than I feared. I will be suspicious of it for a day.", "Fair. Fair is the worst price. It leaves nothing to say."]);
LXP('remark_work', ["Busy with the {job} work, as ever.", "The {job} work keeps me out of trouble.", "Can\'t complain about the {job} work."]);
LXI('remark_work', ["The {job} work is going. I have stopped timing it.", "I think I am good at the {job} work. I have not asked anyone.", "The {job} work has a rhythm. I am slightly behind it.", "At the {job} work, a good day looks identical to a bad one except for the last hour."]);
LXP('joke', ["A gull stole my lunch. I said that\'s theft. It said nothing. Typical lawyer.", "I told the field to grow faster. It grew slower, out of spite.", "My neighbour says the weather\'s turning. It\'s the same weather it\'s always had. New haircut, that\'s all.", "They say good fences make good neighbours. Mine fell over. We get on great.", "I put my boots on the wrong feet this morning and walked all day like that. Nobody said a word. Lovely, I thought.", "Never trust anyone who says they don\'t like bread. Or a gull, come to think of it."]);
LXI('joke', ["I tried to count the days since I arrived. I lost count at the part where I tried to count.", "There is a gull that stands outside the bakery. I think it is in management.", "I planted a turnip and told it the plan. It has not commented.", "I found a very good stone this morning. I put it down again. That is the whole story and I stand by it.", "Someone asked if I had a map. I said the island was the map. He said it was a poor map. We shook on it.", "My bed and I have an understanding. It is mine in the evening and the floor\'s in the morning.", "I tried to whistle a tune I do not know. A bird answered with the same tune. I have not whistled since."]);
LXP('laugh', ["Ha! Good one.", "Ha. That\'s a good one, that.", "You\'ve got me there."]);
LXI('laugh', ["Ha. I will be thinking about that in the night. Thank you.", "Ha. Yes. I will use that on someone who has not heard it.", "Ha. That is the right size for a joke. They are usually too large."]);
LXP('wonder_reply', ["I\'ve wondered that myself.", "Hm. Never thought of it.", "Now you\'ve got me thinking."]);
LXI('wonder_reply', ["I have wondered that too. I did not come to a conclusion. I came to a seat.", "I have no answer. I do have a feeling, and it is the same as yours.", "That is a good question. It will stay with me. I will not thank you."]);
LXP('congratulate', ["Lovely. They grow up fast.", "That\'s wonderful to hear.", "You must be very proud."]);
LXI('congratulate', ["That is wonderful. I mean it in the standard way and a little more.", "You must be proud. It shows in the way you said it, quietly.", "They are doing well, then. It is not always the case. It is good to hear when it is."]);
LXP('hint_noted', ["I\'ll bear that in mind.", "Good to know.", "Is that so? I\'ll remember."]);
LXI('hint_noted', ["I will remember that. I am not promising what I will do with it.", "Noted. I have somewhere to put it.", "Good to know. I will keep it somewhere I can find it."]);

/* ---- what happened to me today: the grounded lines are the best in the game, so they get the most variety ---- */
const LXL = (kind: string, plain: string[], island: string[]) => { for (const t of plain) lx('life:' + kind, 'plain', t); for (const t of island) lxi('life:' + kind, t); };
LXL('planted', ["Got {things} in the ground today.", "Put in {things}. Now it\'s up to the weather.", "Sowed {things} this morning. Fingers crossed.", "{things} went in today. Back aches, but they\'re in."], ["Planted {things}. They went in without objection, which is how it usually goes.", "I put in {things} and stood there a while. It is a good way to spend a standing.", "I sowed {things}. I said a few words over them. It was mostly the weather.", "{things} went in today. I will check on them tomorrow and pretend I did not already."]);
LXL('harvested', ["Brought in {things}. Not a bad haul.", "Got {things} off the field today.", "Harvested {things}. Good to see it come to something.", "{things} in the barn. A fair day\'s work."], ["I harvested {things}. They had been waiting for me, and it was not clear they minded.", "{things}, brought in. I felt briefly like a person with a plan.", "I gathered {things}. I counted them twice. It is a small joy and I allow it.", "The field gave me {things}. I said thank you. I did not know to whom."]);
LXL('bought', ["Bought {things} earlier.", "Got {things} at the stall. Fair price.", "Picked up {things} on the way.", "Treated myself to {things}."], ["I bought {things}. I paid the number I was told, and it was accepted.", "I got {things}. The stall and I understand each other now.", "I bought {things}. I carried them home like a person with a purpose.", "{things}, bought. I did not haggle. I have not learned how, and it is not too late."]);
LXL('sold', ["Sold {things} this morning. Decent price.", "Got rid of {things} at the stall.", "Sold {things}. Every coin helps.", "{things} went at the stall today."], ["I sold {things}. The keeper counted the coins like a man making a promise.", "{things} sold. It felt good and slightly like losing something.", "I sold {things} and walked off with the same face I came with.", "{things} went. I was paid. The arrangement worked, which is rarer than it should be."]);
LXL('baked', ["Baked {things} this morning. Smells wonderful.", "{things} out of the oven. Not bad at all.", "Got {things} baked before the rush.", "{things}, fresh. The whole street knows."], ["I baked {things}. The room smelled like something that would be forgiven.", "{things} out of the oven. They looked at me with their whole crust.", "I baked {things}. I did not burn any. I am noting it for the record.", "{things}. The oven and I worked well together today. I will not mention it to the oven."]);
LXL('cooked', ["Cooked {things} today. Turned out all right.", "Got {things} on the fire. Not bad."], ["I cooked {things}. It was edible, and for some people that is a calling.", "{things}, cooked. The pot and I are friends again."]);
LXL('forged', ["Forged {things} today. Hard on the arms.", "{things} done at the forge. Not pretty. Strong."], ["I forged {things}. The metal agreed, eventually.", "{things}, forged. I looked at them for a while. They looked back, being hard."]);
LXL('woven', ["Wove {things} today. Slow, steady work.", "Got {things} off the loom."], ["I wove {things}. It is a patient trade. The cloth does not hurry and neither do I.", "{things}, woven. I felt, briefly, like a thread."]);
LXL('ate', ["Had a proper meal today. Felt like a new person.", "Ate well. Made all the difference.", "Got a good meal in me at last."], ["I ate properly. I had forgotten how much of the day it fixes.", "I had a meal. It was a good meal. I want that said while it is still true.", "I ate. It was uneventful. I am grateful for the uneventful."]);
LXL('slept', ["Slept well last night. First time in a while.", "Had a good night\'s sleep.", "Slept like the dead."], ["I slept in a bed. I want to say that again, slowly.", "I slept well. I woke up and the day was still there. I counted that as a gift.", "I slept all the way through. I do not know where I went. It was restful."]);
LXL('slept_rough', ["Slept on the ground last night. Never again.", "No bed again. My back\'ll hate me for a week.", "Slept rough. Cold, hard, and I\'m done with it."], ["I slept on the ground. The ground was patient with me. My back has reservations.", "No bed again. I made a nest of what I had. The island heard it and said nothing.", "I slept rough. I have decided to think of it as a short story."]);
LXL('went_hungry', ["Went hungry today. Not a crumb.", "Hardly ate. I could eat a horse.", "Missed my dinner. Stomach\'s been loud all day."], ["I have not eaten today. My stomach has started to make announcements.", "I went without. It is a precise feeling and I recognise it.", "I missed the meal. The day has taken on a certain sharpness."]);
LXL('no_privy', ["Couldn\'t find a privy. I won\'t say what I did.", "Had to make do behind a tree. Not proud of it."], ["I could not find a privy. I made an arrangement with a tree. We both said nothing.", "There was no privy to be had. I will not describe what followed. It was dignified for the most part."]);
LXL('new_in_stock', ["Saw {item} at the {shop}. New in.", "The {shop} has {item} now, if you\'re after some."], ["There is {item} at the {shop}. It was not there before. I noticed because I notice things in the morning.", "The {shop} is stocking {item}. I did not ask why. The shelf looked pleased."]);
LXL('out_of_stock', ["The {shop} had no {item}. Wasted trip.", "Went for {item} and the {shop} had none. Typical."], ["The {shop} had no {item}. I stood there until it felt rude to stay.", "I went for {item}. The {shop} was out. It was very polite about it."]);
LXL('price_up', ["{item} is dearer at the {shop} these days.", "Noticed {item} has gone up at the {shop}. Of course it has."], ["{item} has gone up at the {shop}. Not by much. By enough to be mentioned.", "I noticed {item} costs more at the {shop}. It is a small thing, and I am treating it as a large one."]);
LXL('price_down', ["{item} is cheaper at the {shop}. Worth a trip.", "Good news: {item} is down at the {shop}."], ["{item} is cheaper at the {shop}. I will believe it when I am holding it.", "The {shop} has lowered the price of {item}. I did not ask why. I am enjoying it."]);
LXL('could_not_afford', ["Couldn\'t afford {item} today. Next time.", "Had my eye on {item}, but the purse said no."], ["I could not afford {item}. I looked at it for a long time, to be fair to it.", "I wanted {item} and the purse said no. It has said no before. It is consistent."]);
LXL('tired', ["Worn out today. Could sleep in a ditch.", "Absolutely done in."], ["I am very tired. It has a kind of weight, like a coat.", "I am worn out. The tiredness has started to feel like a place."]);

LXP('shop_greet', ["Hello there.", "Hi. Got a minute?", "Afternoon. Anything good today?", "Hello. Having a quiet day?", "Hello. Is it a busy one?"]);
LXI('shop_greet', ["Hello. I come with a short list and a long hope.", "Good day. I have an errand and a purse.", "Hello. I will be quick, which is what everyone says.", "Hello. I am here for a thing.", "Hello. I was passing and decided to be a customer."]);
LXP('shop_greet_back', ["Hello. What can I do for you?", "Good to see you. What are we after?", "Hello. Take your time.", "Hello there. What\'ll it be?"]);
LXI('shop_greet_back', ["Hello. Tell me what you want and I will tell you what I have.", "Good day. The stall is open and I am at it.", "Hello. I am here, which is the main thing a stall needs.", "Hello. What is it today? I will not guess."]);
for (const t of ['I\'m glad. I was nervous.', 'Good. Good. I wasn\'t sure.', 'Well. That\'s a weight off.']) lx('glad_courtship', 'plain', t);
for (const t of ['Good. I had rehearsed a second answer in case. I will keep it.', 'I am glad. I was a little frightened. That is private.', 'Well. That has gone better than the version in my head.']) lxi('glad_courtship', t);
ACTS.glad_courtship = { kind: 'romance', stage: 'topic', reply: true, when: () => true, w: () => 1, apply: () => {}, replies: [] };
